<?php
require __DIR__.'/entreprise_init.php';
$sql="SELECT u.id_user,u.nom_user,u.prenom_user,COUNT(DISTINCT i.id_form) formations,COALESCE(AVG(NULLIF(p.pourcentage_progression,'')),0) progression FROM t_entreprise_collaborateurs ec INNER JOIN t_utilisateurs u ON u.id_user=ec.id_user LEFT JOIN t_inscriptions i ON i.id_user=u.id_user LEFT JOIN t_progression p ON p.id_user=u.id_user WHERE ec.id_entreprise=? AND ec.statut='actif' GROUP BY u.id_user,u.nom_user,u.prenom_user ORDER BY u.nom_user";$s=$con->prepare($sql);$s->execute([$idEntreprise]);$rows=$s->fetchAll();$active_page='progression.php';
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Progression — TOUN</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="entreprise-menu.css"><link rel="stylesheet" href="entreprise-ui.css"></head><body><?php include __DIR__.'/menu_entreprise.php';?><main class="main-content"><div class="page"><div class="page-head"><div><span class="eyebrow">SUIVI</span><h1>Progression</h1><p>Suivez l'avancement de vos collaborateurs.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Collaborateur</th><th>Formations</th><th>Progression</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="3" class="empty">Aucun collaborateur actif.</td></tr><?php else:foreach($rows as $r):$p=max(0,min(100,(int)round($r['progression'])));?><tr><td><strong><?=e($r['prenom_user'].' '.$r['nom_user'])?></strong></td><td><?=$r['formations']?></td><td style="min-width:220px"><div style="display:flex;align-items:center;gap:7px"><div class="progress" style="flex:1"><span style="width:<?=$p?>%"></span></div><strong><?=$p?>%</strong></div></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></main></body></html>